PROG_VERSION = "\n{prog}  version: 1.2\n\n"

BRIEF_USAGE = """   {prog}  [-i <path to directory>] [-s <positive integer>] [-d <a\n                 string containing two space-seprated positive integers>]\n                 [-n <{{1,2,3,4,5,6}}>] [-r] [-t] [-o] [-q] [--] [--version]\n                 [-h] <Array of strings> ..."""

def print_help(prog):
    sys.stdout.write(PROG_HELP.format(prog=prog))

def print_version(prog):
    sys.stdout.write(PROG_VERSION.format(prog=prog))

