    sys.stderr.write(f"PARSE ERROR: Argument: {arg_short} ({arg_long})\n             Missing a value for this argument!\n\nBrief USAGE: \n{BRIEF_USAGE.format(prog=prog)}\n\nFor complete USAGE and HELP type: \n   {prog} --help\n\n")

