def print_parse_error_nomatch(arg):
    prog = sys.argv[0]
    sys.stderr.write(f"PARSE ERROR: Argument: {arg}\n             Couldn't find match for argument\n\nBrief USAGE: \n{BRIEF_USAGE.format(prog=prog)}\n\nFor complete USAGE and HELP type: \n   {prog} --help\n\n")

