def adjust_dims(w, h, n):
    # n = number of players for map (1..6)
    # returns (w2,h2) rounded down per rules
    if n == 1:
        return (w, h)
    elif n == 2:
        # both even
        w2 = w - (w % 2)
        h2 = h - (h % 2)
        return (w2, h2)
    elif n == 3:
        w2 = w - (w % 3)
        h2 = h - (h % 3)
        return (w2, h2)
    elif n == 4:
        # width multiple of 8, height even
        w2 = w - (w % 8)
        h2 = h - (h % 2)
        return (w2, h2)
    elif n == 5:
        w2 = w - (w % 5)
        h2 = h - (h % 5)
        return (w2, h2)
    elif n == 6:
        w2 = w - (w % 12)
        h2 = h - (h % 3)
        return (w2, h2)
    else:
        return (w, h)

