class Bot:
    def __init__(self, cmd, player_id):
        self.cmd = cmd
        self.id = player_id
        self.proc = None
        self.name = ""
        self.alive = True
        self.errored = False
        self.error_type = None  # 'timeout', 'invalid', 'exit'
        self.log_lines = []  # for log file
        self.init_time_ms = 0
        self.lock = threading.Lock()

    def start(self):
        # launch via sh -c, merge stderr to stdout
        self.proc = subprocess.Popen(
            ["sh", "-c", self.cmd],
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            bufsize=1,
        )
        # Use binary mode, handle manually
    def send_line(self, s):
        try:
            self.proc.stdin.write((s).encode() if isinstance(s, str) else s)
            self.proc.stdin.flush()
            return True
        except:
            return False
    def recv_line_timeout(self, timeout):
        # timeout in seconds, None for infinite
        # Use thread to read with timeout
        q = queue.Queue()
        def _read():
            try:
                line = self.proc.stdout.readline()
                q.put(line)
            except Exception as e:
                q.put(e)
        t = threading.Thread(target=_read, daemon=True)
        t.start()
        try:
            if timeout is None:
                line = q.get()
            else:
                line = q.get(timeout=timeout)
            if isinstance(line, Exception):
                return None, 'error'
            if line == b'' or line == '' or line is None:
                # EOF: bot exited, no data
                return None, 'eof'
            # decode as utf-8, replace? Original handles? Assume utf-8, strip trailing \r\n? Keep as is for validation?
            if isinstance(line, bytes):
                try:
                    s = line.decode('utf-8', errors='strict')
                except:
                    # invalid utf-8? Treat as invalid character?
                    return line, 'invalid'
            else:
                s = line
            return s, 'ok'
        except queue.Empty:
            return None, 'timeout'

    def kill(self):
        try:
            self.proc.kill()
        except:
            pass
        try:
            self.proc.wait(timeout=0.5)
        except:
            pass

