def adjust_dims(w,h,n):
    if n==1: return (w,h)
    elif n==2: return (w-(w%2), h-(h%2))
    elif n==3: return (w-(w%3), h-(h%3))
    elif n==4: return (w-(w%8), h-(h%2))
    elif n==5: return (w-(w%5), h-(h%5))
    elif n==6: return (w-(w%12), h-(h%3))
    else: return (w,h)

def random_dims():
    t=int(time.time())
    r=random.Random(t)
    ch=[20,25,30,35,40,45,50]
    v=r.choice(ch)
    return (v,v)

def random_seed():
    now=time.time()
    sec=int(now); micro=int((now-sec)*1e6)
    return (sec*1000000+micro) % (2**32)

def generate_map(W,H,n_map,seed):
    rng=random.Random((seed,W,H,n_map))
    base=[[rng.randint(0,10) for _ in range(W)] for _ in range(H)]
    def blur(g):
        ng=[[0]*W for _ in range(H)]
        for y in range(H):
            for x in range(W):
                s=0
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        s+=g[(y+dy)%H][(x+dx)%W]
                ng[y][x]=s//9
        return ng
    prod=blur(blur(base))
    for y in range(H):
        for x in range(W):
            if prod[y][x]>16: prod[y][x]=16
    strengths=[[0]*W for _ in range(H)]
    for y in range(H):
        for x in range(W):
            p=prod[y][x]
            noise=rng.randint(0,60)
            s=p*12+noise+20
            if s>255: s=255
            strengths[y][x]=s
    def blur_s(g):
        ng=[[0]*W for _ in range(H)]
        for y in range(H):
            for x in range(W):
                s=0
                for dy in (-1,0,1):
                    for dx in (-1,0,1):
                        s+=g[(y+dy)%H][(x+dx)%W]
                ng[y][x]=s//9
        return ng
    strengths=blur_s(strengths)
    # spawns
    if n_map==1:
        spawns=[(W//2,H//2)]
    elif n_map==2:
        spawns=[(W//2,H//4),(W//2,H-H//4-1)]
    elif n_map==3:
        spawns=[(W//2,H//4),(W//4,(3*H)//4),((3*W)//4,(3*H)//4)]
    elif n_map==4:
        spawns=[(W//4,H//4),((3*W)//4,H//4),(W//4,(3*H)//4),((3*W)//4,(3*H)//4)]
    elif n_map==5:
        spawns=[(W//2,H//4),(W//4,H//2),((3*W)//4,H//2),(W//3,(3*H)//4),((2*W)//3,(3*H)//4)]
    elif n_map==6:
        spawns=[(W//6,H//3),((3*W)//6,H//3),((5*W)//6,H//3),(W//6,(2*H)//3),((3*W)//6,(2*H)//3),((5*W)//6,(2*H)//3)]
    else:
        spawns=[(W//2,H//2)]
    # clamp
    nsp=[]
    for (x,y) in spawns:
        nsp.append((x%W,y%H))
    return prod,strengths,nsp

def fmt_rle(own,W,H):
    flat=[]
    for y in range(H):
        for x in range(W):
            flat.append(own[y][x])
    if not flat: return ""
    parts=[]
    cur=flat[0]; cnt=1
    for v in flat[1:]:
        if v==cur: cnt+=1
        else:
            parts.append(f"{cnt} {cur}"); cur=v; cnt=1
    parts.append(f"{cnt} {cur}")
    return " ".join(parts)+" "

def fmt_stre(stre,W,H):
    parts=[]
    for y in range(H):
        for x in range(W):
            parts.append(str(stre[y][x]))
    return " ".join(parts)+" "

