    # moves: dict (x,y)->dir (as sent, may be >4)
    # production
    new_own=[row[:] for row in own]
    new_stre=[row[:] for row in stre]
    for y in range(H):
        for x in range(W):
            o=own[y][x]
            if o==0: continue
            d=moves.get((x,y),0)
            if d==0:
                ns=new_stre[y][x]+prod[y][x]
                if ns>255: ns=255
                new_stre[y][x]=ns
            elif 1<=d<=4:
                pass
            else:
                pass
    # incoming
    incoming=[[dict() for _ in range(W)] for _ in range(H)]
    moving_src=set()
    for y in range(H):
        for x in range(W):
            o=own[y][x]
            if o==0: continue
            d=moves.get((x,y),0)
            if d==0:
                s=new_stre[y][x]
                dd=incoming[y][x]
                dd[o]=dd.get(o,0)+s
            elif 1<=d<=4:
                s=stre[y][x]
                nx,ny=x,y
                if d==1: ny=(y-1)%H
                elif d==2: nx=(x+1)%W
                elif d==3: ny=(y+1)%H
                elif d==4: nx=(x-1)%W
                dd=incoming[ny][nx]
                dd[o]=dd.get(o,0)+s
                moving_src.add((x,y))
            else:
                s=stre[y][x]
                dd=incoming[y][x]
                dd[o]=dd.get(o,0)+s
    for y in range(H):
        for x in range(W):
            if own[y][x]==0:
                s=stre[y][x]
                dd=incoming[y][x]
                dd[0]=dd.get(0,0)+s
    for y in range(H):
        for x in range(W):
            dd=incoming[y][x]
            if not dd:
                new_own[y][x]=own[y][x]
                new_stre[y][x]=0
                continue
            if len(dd)==1:
                p,s=list(dd.items())[0]
                if s>255: s=255
                new_own[y][x]=p
                new_stre[y][x]=s
            else:
                srt=sorted(dd.items(),key=lambda kv: kv[1],reverse=True)
                mp,ms=srt[0]; ss=srt[1][1]
                if ms>ss:
                    ns=ms-ss
                    if ns>255: ns=255
                    new_own[y][x]=mp
                    new_stre[y][x]=ns
                else:
                    new_own[y][x]=mp
                    new_stre[y][x]=0
    return new_own,new_stre

